package com.soprasteria.g4it.backend.external.ecologits.model.request;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.Data;
import lombok.experimental.SuperBuilder;

/**
 * Request body for the EcoLogits "/v1beta/estimations" endpoint.
 */
@Data
@SuperBuilder
@JsonInclude(JsonInclude.Include.NON_NULL)
public class EcoEstimationRequestRest {

    /**
     * Provider identifier (e.g. openai, mistralai, anthropic...).
     */
    private String provider;

    /**
     * Model identifier as registered in EcoLogits (e.g. gpt-4o-mini).
     */
    @JsonProperty("model_name")
    private String modelName;

    /**
     * Number of tokens generated by the model.
     */
    @JsonProperty("output_token_count")
    private Integer outputTokenCount;

    /**
     * Measured request latency in seconds (optional).
     */
    @JsonProperty("request_latency")
    private Double requestLatency;

    /**
     * ISO 3166-1 alpha-3 zone code for the electricity mix. Defaults to "WOR" (world average) when not set.
     */
    @JsonProperty("electricity_mix_zone")
    private String electricityMixZone;

}